package com.example.domain.model.i18n

internal object DuaBn1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("ঘুম থেকে জাগার পর", "সকল প্রশংসা আল্লাহর, যিনি আমাদের মৃত্যু (ঘুম) দেওয়ার পর জীবিত করেছেন, আর তাঁরই কাছে পুনরুত্থান।", "ঘুম থেকে জেগেই আল্লাহর শুকরিয়া আদায়ের জন্য।", "নবী ﷺ ঘুম থেকে জেগে এই দোয়া পড়তেন — দিনের শুরু কৃতজ্ঞতা ও আখিরাতের স্মরণে।"),
        "dua_leaving_home" to DuaText("ঘর থেকে বের হওয়ার সময়", "আল্লাহর নামে; আমি আল্লাহর উপর ভরসা করলাম। আল্লাহ ছাড়া কোনো শক্তি নেই, কোনো ক্ষমতা নেই।", "ঘর থেকে বাইরে পা রাখার সময় আল্লাহর হেফাজতের জন্য।", "ফেরেশতারা বলেন: 'তোমাকে হেদায়েত দেওয়া হলো, তোমার জন্য যথেষ্ট করা হলো এবং তোমাকে রক্ষা করা হলো', আর শয়তান দূরে সরে যায়।"),
        "dua_anxiety_distress" to DuaText("দুশ্চিন্তা ও দুঃখ থেকে মুক্তি", "হে আল্লাহ! আমি তোমার কাছে আশ্রয় চাই দুশ্চিন্তা ও দুঃখ থেকে, অক্ষমতা ও অলসতা থেকে, কৃপণতা ও কাপুরুষতা থেকে, ঋণের বোঝা ও মানুষের আধিপত্য থেকে।", "দুঃখ, দুশ্চিন্তা, ঋণের বোঝা ও মানসিক কষ্টের সময়।", "নবী ﷺ এই দোয়া বেশি বেশি করতেন — দুঃখ, অলসতা ও ঋণের চিন্তা থেকে আশ্রয়।"),
        "dua_sayyidul_istighfar" to DuaText("সাইয়্যিদুল ইস্তিগফার", "হে আল্লাহ! তুমিই আমার রব, তুমি ছাড়া কোনো ইলাহ নেই। তুমি আমাকে সৃষ্টি করেছ এবং আমি তোমার বান্দা, আমি সাধ্যমতো তোমার অঙ্গীকার ও প্রতিশ্রুতির উপর আছি। আমার কৃতকর্মের অনিষ্ট থেকে তোমার আশ্রয় চাই। আমার উপর তোমার নিয়ামত স্বীকার করছি এবং আমার গুনাহও স্বীকার করছি, অতএব আমাকে ক্ষমা করো, কারণ তুমি ছাড়া কেউ গুনাহ ক্ষমা করে না।", "সকাল ও সন্ধ্যা — নবী ﷺ-এর শেখানো তওবার সর্বোত্তম দোয়া।", "যে দৃঢ় বিশ্বাসে সন্ধ্যায় পড়ে সেই রাতে মারা যায় সে জান্নাতে যাবে; সকালে পড়লেও একই ফজিলত।"),
        "dua_parents" to DuaText("পিতা-মাতার জন্য দোয়া", "হে আমার রব! তাঁদের উভয়ের প্রতি দয়া করো, যেমন তাঁরা শৈশবে আমাকে লালন-পালন করেছেন।", "পিতা-মাতার জন্য কুরআনি দোয়া — শৈশবের লালন-পালনের প্রতিদানে।", "আল্লাহ নিজেই পিতা-মাতার জন্য এই দোয়া করার আদেশ দিয়েছেন।"),
        "dua_entering_mosque" to DuaText("মসজিদে প্রবেশ", "হে আল্লাহ! আমার জন্য তোমার রহমতের দরজাগুলো খুলে দাও।", "ডান পা দিয়ে মসজিদে প্রবেশের সময়।", "নবী ﷺ মসজিদে প্রবেশের সময় এই দোয়া পড়ার শিক্ষা দিয়েছেন।"),
        "dua_morning_asbahna" to DuaText("সকালের জিকির", "আমরা সকালে উপনীত হলাম এবং সমস্ত রাজত্বও আল্লাহর জন্য সকালে উপনীত হলো। সকল প্রশংসা আল্লাহর। আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক, তাঁর কোনো শরিক নেই। রাজত্ব তাঁরই, প্রশংসা তাঁরই এবং তিনি সব কিছুর উপর ক্ষমতাবান।", "সকালে পড়ার মাসনুন দোয়া।", "দিনের শুরু হয় আল্লাহর রাজত্ব ও তাওহিদের স্বীকৃতি দিয়ে।"),
        "dua_evening_amsayna" to DuaText("সন্ধ্যার জিকির", "আমরা সন্ধ্যায় উপনীত হলাম এবং সমস্ত রাজত্বও আল্লাহর জন্য সন্ধ্যায় উপনীত হলো। সকল প্রশংসা আল্লাহর। আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক, তাঁর কোনো শরিক নেই। রাজত্ব তাঁরই, প্রশংসা তাঁরই এবং তিনি সব কিছুর উপর ক্ষমতাবান।", "সন্ধ্যায় পড়ার মাসনুন দোয়া।", "রাতের শুরু হয় আল্লাহর রাজত্ব ও তাওহিদের স্বীকৃতি দিয়ে।"),
        "dua_bismillah_la_yadurru" to DuaText("সব ক্ষতি থেকে হেফাজত", "আল্লাহর নামে, যাঁর নামের সাথে আসমান ও জমিনের কোনো কিছুই ক্ষতি করতে পারে না, আর তিনি সর্বশ্রোতা, সর্বজ্ঞ।", "সকালে ও সন্ধ্যায় তিনবার করে।", "যে সকাল-সন্ধ্যা তিনবার পড়বে, কোনো কিছু তার ক্ষতি করবে না।"),
        "dua_raditu_billahi" to DuaText("আল্লাহকে রব হিসেবে সন্তুষ্ট", "আমি আল্লাহকে রব হিসেবে, ইসলামকে দ্বীন হিসেবে এবং মুহাম্মাদ ﷺ-কে নবী হিসেবে পেয়ে সন্তুষ্ট।", "সকাল ও সন্ধ্যায় তিনবার।", "কিয়ামতের দিন তাকে সন্তুষ্ট করা আল্লাহর উপর তার অধিকার হয়ে যায়।"),
        "dua_hasbiyallah" to DuaText("হাসবিয়াল্লাহ (আল্লাহই যথেষ্ট)", "আল্লাহই আমার জন্য যথেষ্ট, তিনি ছাড়া কোনো ইলাহ নেই, তাঁরই উপর আমি ভরসা করলাম এবং তিনি মহান আরশের রব।", "সকাল ও সন্ধ্যায় সাতবার।", "কুরআনের আয়াত; দুনিয়া ও আখিরাতের দুশ্চিন্তায় আল্লাহ যথেষ্ট হয়ে যান।"),
        "dua_subhanallah_wa_bihamdihi" to DuaText("সুবহানাল্লাহি ওয়া বিহামদিহি", "আল্লাহ পবিত্র এবং সকল প্রশংসা তাঁরই।", "দিনে একশ বার।", "যে দিনে একশ বার বলে, তার গুনাহ ক্ষমা করা হয়, যদিও তা সমুদ্রের ফেনার সমান হয়।"),
        "dua_tahleel_100" to DuaText("লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু", "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক, তাঁর কোনো শরিক নেই। রাজত্ব ও প্রশংসা তাঁরই এবং তিনি সব কিছুর উপর ক্ষমতাবান।", "দিনে একশ বার পড়ার বড় ফজিলত।", "দশজন দাস মুক্ত করার সওয়াব, একশ নেকি, একশ গুনাহ মাফ এবং সন্ধ্যা পর্যন্ত শয়তান থেকে হেফাজত।"),
        "dua_leaving_mosque" to DuaText("মসজিদ থেকে বের হওয়া", "হে আল্লাহ! আমি তোমার কাছে তোমার অনুগ্রহ চাই।", "বাম পা দিয়ে মসজিদ থেকে বের হওয়ার সময়।", "মসজিদ থেকে বের হতে আল্লাহর অনুগ্রহ ও রিজিকের প্রার্থনা।"),
        "dua_after_adhan" to DuaText("আজানের পর", "হে আল্লাহ! এই পরিপূর্ণ আহ্বান ও প্রতিষ্ঠিত হতে যাওয়া নামাজের রব! মুহাম্মাদ ﷺ-কে ওসিলা ও মর্যাদা দান করো এবং তাঁকে সেই প্রশংসিত স্থানে পৌঁছাও যার ওয়াদা তুমি তাঁকে দিয়েছ।", "আজান শেষ হওয়ার পর।", "যে এই দোয়া পড়ে, কিয়ামতের দিন তার জন্য নবী ﷺ-এর শাফায়াত অবধারিত হয়।"),
        "dua_after_salah_istighfar" to DuaText("ফরজ নামাজের পর", "আমি আল্লাহর কাছে ক্ষমা চাই (৩ বার)। হে আল্লাহ! তুমিই সালাম এবং তোমার থেকেই শান্তি, তুমি বরকতময় হে মহিমা ও সম্মানের অধিকারী।", "সালাম ফেরানোর সঙ্গে সঙ্গে।", "নবী ﷺ প্রত্যেক ফরজ নামাজের পর এটি পড়তেন।"),
        "dua_after_salah_help_dhikr" to DuaText("তোমার জিকিরে আমাকে সাহায্য করো", "হে আল্লাহ! তোমার জিকির, তোমার শুকরিয়া এবং তোমার উত্তম ইবাদতে আমাকে সাহায্য করো।", "প্রত্যেক নামাজের পর — নবী ﷺ মুআয (রা.)-কে অসিয়ত করেছেন।", "নবী ﷺ-এর বিশেষ অসিয়ত — ইবাদতে সৌন্দর্য ও অবিচলতা।"),
        "dua_ayatul_kursi" to DuaText("নামাজের পর আয়াতুল কুরসি", "আল্লাহ, তিনি ছাড়া কোনো ইলাহ নেই, তিনি চিরঞ্জীব, সব কিছুর ধারক। তাঁকে তন্দ্রাও স্পর্শ করে না, নিদ্রাও না। আসমান ও জমিনে যা কিছু আছে সবই তাঁর। কে আছে যে তাঁর অনুমতি ছাড়া তাঁর কাছে সুপারিশ করবে? তিনি জানেন যা তাদের সামনে ও পেছনে আছে, আর তারা তাঁর জ্ঞানের কিছুই আয়ত্ত করতে পারে না, তবে যতটুকু তিনি চান। তাঁর কুরসি আসমান ও জমিন পরিবেষ্টন করে আছে, আর এগুলোর রক্ষণাবেক্ষণ তাঁকে ক্লান্ত করে না, তিনি সর্বোচ্চ, মহান।", "প্রত্যেক ফরজ নামাজের পর এবং ঘুমানোর আগে।", "প্রত্যেক ফরজ নামাজের পর পাঠকারীকে জান্নাতে যেতে শুধু মৃত্যুই বাধা; ঘুমানোর আগে পড়লে সকাল পর্যন্ত হেফাজত।"),
        "dua_before_sleep" to DuaText("ঘুমানোর আগে", "হে আল্লাহ! তোমার নামেই আমি মরি (ঘুমাই) এবং জীবিত হই (জাগি)।", "বিছানায় শোয়ার পর।", "নবী ﷺ ঘুমানোর আগে এই দোয়া পড়তেন।"),
        "dua_sleep_tasbeeh" to DuaText("ঘুমানোর আগে তাসবিহে ফাতেমি", "আল্লাহ পবিত্র (৩৩), সকল প্রশংসা আল্লাহর (৩৩), আল্লাহ সবচেয়ে বড় (৩৪)।", "ঘুমানোর আগে — নবী ﷺ ফাতিমা ও আলী (রা.)-কে শিখিয়েছেন।", "নবী ﷺ বলেছেন এটি তোমাদের জন্য খাদেমের চেয়ে উত্তম।"),
        "dua_sleep_qina_adhab" to DuaText("আজাব থেকে হেফাজত", "হে আল্লাহ! যেদিন তুমি তোমার বান্দাদের পুনরুত্থিত করবে সেদিন আমাকে তোমার আজাব থেকে রক্ষা করো।", "ডান হাত গালের নিচে রেখে তিনবার।", "ঘুমকে মৃত্যুর স্মরণ ও আখিরাতের প্রস্তুতি বানিয়ে দেয়।"),
        "dua_bad_dream" to DuaText("খারাপ স্বপ্ন দেখলে", "আমি বিতাড়িত শয়তান থেকে আল্লাহর আশ্রয় চাই।", "খারাপ স্বপ্ন দেখলে: বাম দিকে তিনবার হালকা থুথু ফেলুন, তারপর পাশ ফিরুন।", "খারাপ স্বপ্ন ক্ষতি করবে না; কাউকে বলবেন না।"),
        "dua_yunus" to DuaText("ইউনুস (আ.)-এর দোয়া", "তুমি ছাড়া কোনো ইলাহ নেই, তুমি পবিত্র, নিশ্চয়ই আমি জালিমদের অন্তর্ভুক্ত ছিলাম।", "মাছের পেটে ইউনুস (আ.)-এর দোয়া — সব বিপদে।", "যে মুসলিম যেকোনো বিষয়ে এই দোয়া করে, আল্লাহ তার দোয়া কবুল করেন।"),
        "dua_karb" to DuaText("কঠিন বিপদের দোয়া", "আল্লাহ ছাড়া কোনো ইলাহ নেই, যিনি মহান, সহনশীল। আল্লাহ ছাড়া কোনো ইলাহ নেই, যিনি মহান আরশের রব। আল্লাহ ছাড়া কোনো ইলাহ নেই, যিনি আসমানসমূহের রব, জমিনের রব এবং সম্মানিত আরশের রব।", "কঠিন বিপদ ও কষ্টের সময়।", "নবী ﷺ বিপদের সময় এই দোয়া পড়তেন।"),
        "dua_ya_hayyu_ya_qayyum" to DuaText("ইয়া হাইয়ু ইয়া কাইয়ুম", "হে চিরঞ্জীব, হে সব কিছুর ধারক! তোমার রহমতের উসিলায় আমি সাহায্য চাই।", "যখন কোনো বিষয় খুব ভারী হয়ে যায়।", "কোনো বিষয় নবী ﷺ-কে চিন্তিত করলে তিনি এটি পড়তেন।"),
        "dua_hasbunallah" to DuaText("হাসবুনাল্লাহু ওয়া নিমাল ওয়াকিল", "আল্লাহই আমাদের জন্য যথেষ্ট এবং তিনি উত্তম কর্মবিধায়ক।", "শত্রুর ভয় বা বড় বিপদের সময়।", "ইবরাহিম (আ.) আগুনে নিক্ষিপ্ত হওয়ার সময় এবং নবী ﷺ বিপদের সময় এটি বলেছেন।"),
        "dua_entering_home" to DuaText("ঘরে প্রবেশ", "আল্লাহর নামে।", "ঘরে প্রবেশের সময় আল্লাহর নাম নিন ও সালাম দিন।", "ঘরে প্রবেশ ও খাওয়ার সময় আল্লাহর জিকির করলে শয়তান বলে: এখানে তোমাদের রাত কাটানোর জায়গা নেই, খাবারও নেই।"),
        "dua_travel" to DuaText("সফরের (বাহনের) দোয়া", "পবিত্র সেই সত্তা যিনি একে আমাদের বশীভূত করে দিয়েছেন, অথচ আমরা একে বশ করতে সক্ষম ছিলাম না, আর নিশ্চয়ই আমরা আমাদের রবের দিকে ফিরে যাব।", "বাহনে বসে তিনবার আল্লাহু আকবার বলার পর।", "সফরের মাসনুন দোয়া — হেফাজত ও বরকতের জন্য।"),
        "dua_entering_market" to DuaText("বাজারে প্রবেশ", "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক, তাঁর কোনো শরিক নেই। রাজত্ব ও প্রশংসা তাঁরই। তিনিই জীবন দেন ও মৃত্যু দেন, তিনি চিরঞ্জীব, কখনো মরবেন না। তাঁর হাতেই কল্যাণ এবং তিনি সব কিছুর উপর ক্ষমতাবান।", "বাজারে প্রবেশের সময়।", "হাদিসে এর বড় ফজিলত বর্ণিত হয়েছে (লক্ষ লক্ষ নেকি)।"),
        "dua_adam_forgiveness" to DuaText("আদম (আ.)-এর দোয়া", "হে আমাদের রব! আমরা নিজেদের উপর জুলুম করেছি, আর যদি তুমি আমাদের ক্ষমা না করো এবং দয়া না করো, তবে অবশ্যই আমরা ক্ষতিগ্রস্তদের অন্তর্ভুক্ত হব।", "আদম ও হাওয়া (আ.)-এর তওবার দোয়া।", "মানবজাতির প্রথম তওবা — আল্লাহ তা কবুল করেছেন।"),
        "dua_abu_bakr" to DuaText("আবু বকর (রা.)-কে শেখানো দোয়া", "হে আল্লাহ! আমি নিজের উপর অনেক জুলুম করেছি, আর তুমি ছাড়া কেউ গুনাহ ক্ষমা করে না, অতএব তোমার পক্ষ থেকে আমাকে ক্ষমা করো এবং আমার প্রতি দয়া করো, নিশ্চয়ই তুমি ক্ষমাশীল, দয়ালু।", "নামাজে (তাশাহহুদের পর) পড়ার জন্য নবী ﷺ আবু বকর সিদ্দিক (রা.)-কে শিখিয়েছেন।", "নামাজের শেষে পড়ার মাসনুন দোয়া।"),
        "dua_astaghfirullah_atubu" to DuaText("দৈনিক ইস্তিগফার", "আমি আল্লাহর কাছে ক্ষমা চাই এবং তাঁর দিকে তওবা করি।", "নবী ﷺ দিনে সত্তর বারের বেশি ইস্তিগফার করতেন।", "নবী ﷺ বলেছেন: আমি দিনে সত্তর বারের বেশি আল্লাহর কাছে ক্ষমা চাই ও তওবা করি।"),
        "dua_laylatul_qadr" to DuaText("লাইলাতুল কদরের দোয়া", "হে আল্লাহ! তুমি অতিশয় ক্ষমাশীল, ক্ষমা করতে ভালোবাসো, অতএব আমাকে ক্ষমা করো।", "আয়েশা (রা.)-কে লাইলাতুল কদরের জন্য শেখানো হয়েছে।", "রমজানের শেষ রাতগুলো ও লাইলাতুল কদরের বিশেষ দোয়া।"),
        "dua_family_coolness" to DuaText("চোখের শীতলতা (স্ত্রী-সন্তান)", "হে আমাদের রব! আমাদের স্ত্রী ও সন্তানদের থেকে আমাদের চোখের শীতলতা দান করো এবং আমাদের মুত্তাকিদের ইমাম বানাও।", "নেক স্ত্রী/স্বামী ও সন্তানের জন্য কুরআনি দোয়া।", "ঘরে শান্তি ও নেক সন্তানের জন্য।"),
        "dua_righteous_children" to DuaText("নেক সন্তানের জন্য", "হে আমার রব! তোমার পক্ষ থেকে আমাকে পবিত্র সন্তান দান করো, নিশ্চয়ই তুমি দোয়া শ্রবণকারী।", "জাকারিয়া (আ.)-এর দোয়া।", "সন্তান কামনার কুরআনি দোয়া।"),
        "dua_ibrahim_prayer_family" to DuaText("নামাজ কায়েমকারী", "হে আমার রব! আমাকে ও আমার সন্তানদের নামাজ কায়েমকারী বানাও। হে আমাদের রব! আমার দোয়া কবুল করো। হে আমাদের রব! হিসাবের দিন আমাকে, আমার পিতা-মাতাকে এবং সকল মুমিনকে ক্ষমা করো।", "ইবরাহিম (আ.)-এর নিজের ও সন্তানদের জন্য দোয়া।", "সাধারণত নামাজের শেষে পড়া হয়।"),
        "dua_newlywed" to DuaText("নবদম্পতিকে অভিনন্দন", "আল্লাহ তোমার জন্য বরকত দিন, তোমার উপর বরকত নাজিল করুন এবং তোমাদের দুজনকে কল্যাণে একত্রিত রাখুন।", "বিয়ে করা ব্যক্তিকে অভিনন্দন জানানোর সময়।", "বিয়ের মাসনুন অভিনন্দন।"),
        "dua_before_eating" to DuaText("খাওয়ার আগে", "আল্লাহর নামে। (ভুলে গেলে:) আল্লাহর নামে, এর শুরুতে ও শেষে।", "খাওয়ার আগে। ভুলে গেলে মাঝখানে পড়ুন।", "বিসমিল্লাহ পড়লে খাবারে শয়তান শরিক হয় না।"),
        "dua_after_eating" to DuaText("খাওয়ার পর", "সকল প্রশংসা আল্লাহর, যিনি আমাকে এটি খাইয়েছেন এবং আমার কোনো শক্তি ও সামর্থ্য ছাড়াই এই রিজিক দিয়েছেন।", "খাওয়া শেষ করার পর।", "পাঠকারীর পূর্বের গুনাহ ক্ষমা করা হয়।"),
        "dua_host" to DuaText("মেজবানের জন্য", "হে আল্লাহ! তুমি তাদের যে রিজিক দিয়েছ তাতে বরকত দাও, তাদের ক্ষমা করো এবং তাদের প্রতি দয়া করো।", "কারও বাড়িতে খাওয়ার পর মেজবানের জন্য।", "মাসনুন পদ্ধতিতে মেজবানকে ধন্যবাদ।"),
        "dua_breaking_fast" to DuaText("ইফতারের সময়", "পিপাসা দূর হলো, শিরাগুলো সিক্ত হলো এবং আল্লাহ চাইলে প্রতিদান নিশ্চিত হলো।", "ইফতারের সময়।", "নবী ﷺ ইফতারের সময় এটি বলতেন।"),
        "dua_new_clothes" to DuaText("নতুন কাপড় পরা", "হে আল্লাহ! সকল প্রশংসা তোমার, তুমিই আমাকে এটি পরিয়েছ। আমি তোমার কাছে এর কল্যাণ এবং যে উদ্দেশ্যে এটি তৈরি তার কল্যাণ চাই, আর এর অনিষ্ট ও যে উদ্দেশ্যে তৈরি তার অনিষ্ট থেকে তোমার আশ্রয় চাই।", "নতুন কাপড় পরার সময় (কাপড়ের নাম নিয়ে, যেমন জামা বা পাগড়ি)।", "নবী ﷺ নতুন কাপড় পরলে এই দোয়া করতেন। (প্রতিদিন কাপড় পরার দোয়া 'কাপড় পরা'-তে আছে।)"),
        "dua_rabbana_atina" to DuaText("দুনিয়া ও আখিরাতের কল্যাণ", "হে আমাদের রব! আমাদের দুনিয়াতে কল্যাণ দাও এবং আখিরাতেও কল্যাণ দাও, আর আমাদের আগুনের আজাব থেকে রক্ষা করো।", "নবী ﷺ সবচেয়ে বেশি এই দোয়া করতেন।", "দুনিয়া ও আখিরাতের সব কল্যাণ একত্রকারী দোয়া।"),
        "dua_rabbi_zidni_ilma" to DuaText("জ্ঞান বৃদ্ধি", "হে আমার রব! আমার জ্ঞান বৃদ্ধি করো।", "জ্ঞান বৃদ্ধির জন্য।", "আল্লাহ নবী ﷺ-কে শুধু জ্ঞান বৃদ্ধির দোয়া করার আদেশ দিয়েছেন।"),
        "dua_musa_sharh_sadr" to DuaText("বক্ষ প্রশস্তের দোয়া (মুসা আ.)", "হে আমার রব! আমার বক্ষ প্রশস্ত করে দাও, আমার কাজ সহজ করে দাও এবং আমার জিহ্বার জড়তা দূর করে দাও, যাতে তারা আমার কথা বুঝতে পারে।", "পরীক্ষা, বক্তৃতা বা কোনো কঠিন কাজের আগে।", "মুসা (আ.)-এর দোয়া — অন্তরের প্রশান্তি ও কাজে সহজতা।"),
        "dua_la_tuzigh" to DuaText("অন্তরের দৃঢ়তা", "হে আমাদের রব! হেদায়েত দেওয়ার পর আমাদের অন্তর বক্র করো না এবং তোমার পক্ষ থেকে আমাদের রহমত দান করো, নিশ্চয়ই তুমি মহাদাতা।", "হেদায়েতের উপর অবিচল থাকার জন্য।", "ঈমানের উপর দৃঢ় থাকার দোয়া।"),
        "dua_ya_muqallib" to DuaText("হে অন্তর পরিবর্তনকারী", "হে অন্তর পরিবর্তনকারী! আমার অন্তরকে তোমার দ্বীনের উপর অবিচল রাখো।", "নবী ﷺ প্রায়ই এই দোয়া করতেন।", "উম্মে সালামা (রা.)-এর বর্ণনামতে নবী ﷺ-এর সবচেয়ে বেশি করা দোয়া।"),
        "dua_la_tuakhidhna" to DuaText("সূরা বাকারার শেষ আয়াত", "হে আমাদের রব! আমরা যদি ভুলে যাই বা ভুল করি, তবে আমাদের পাকড়াও করো না। হে আমাদের রব! আমাদের উপর এমন বোঝা চাপিও না যেমন আমাদের পূর্ববর্তীদের উপর চাপিয়েছিলে। হে আমাদের রব! আমাদের উপর এমন ভার দিও না যা বহনের শক্তি আমাদের নেই। আমাদের মাফ করো, ক্ষমা করো এবং দয়া করো। তুমিই আমাদের অভিভাবক, অতএব কাফির সম্প্রদায়ের বিরুদ্ধে আমাদের সাহায্য করো।", "রাতে ঘুমানোর আগে — সূরা বাকারার শেষ দুই আয়াত।", "যে রাতে সূরা বাকারার শেষ দুই আয়াত পড়ে, তা তার জন্য যথেষ্ট হয়।"),
        "dua_visiting_sick" to DuaText("অসুস্থকে দেখতে যাওয়া", "আমি মহান আল্লাহর কাছে, যিনি মহান আরশের রব, প্রার্থনা করি যেন তিনি তোমাকে আরোগ্য দান করেন।", "অসুস্থকে দেখতে গিয়ে সাতবার।", "মৃত্যুর সময় না হয়ে থাকলে আল্লাহ তাকে আরোগ্য দান করেন।"),
        "dua_ruqyah_pain" to DuaText("শারীরিক ব্যথার জন্য", "আমি আল্লাহ ও তাঁর কুদরতের আশ্রয় চাই সেই কষ্টের অনিষ্ট থেকে যা আমি অনুভব করছি এবং যার আশঙ্কা করছি।", "ব্যথার জায়গায় হাত রেখে তিনবার বিসমিল্লাহ, তারপর সাতবার এই দোয়া।", "নবী ﷺ উসমান ইবনে আবিল আস (রা.)-কে ব্যথার জন্য শিখিয়েছেন।"),
        "dua_ruqyah_nabawi" to DuaText("অসুস্থের জন্য নববী রুকইয়া", "হে আল্লাহ, মানুষের রব! কষ্ট দূর করো, আরোগ্য দাও, তুমিই আরোগ্যদাতা, তোমার আরোগ্য ছাড়া কোনো আরোগ্য নেই, এমন আরোগ্য যা কোনো রোগ অবশিষ্ট রাখে না।", "অসুস্থের উপর হাত বুলিয়ে।", "নবী ﷺ পরিবারের অসুস্থদের দেখতে গিয়ে এটি পড়তেন।"),
        "dua_kalimat_tammat" to DuaText("পরিপূর্ণ কালিমার আশ্রয়", "আমি আল্লাহর পরিপূর্ণ কালিমাসমূহের আশ্রয় চাই তাঁর সৃষ্টির অনিষ্ট থেকে।", "কোথাও যাত্রাবিরতি বা সন্ধ্যায়।", "যে কোথাও নেমে এটি পড়ে, সেখান থেকে যাওয়া পর্যন্ত কিছুই তার ক্ষতি করবে না।"),
        "dua_evil_eye" to DuaText("শিশুদের হেফাজত (বদনজর)", "আমি তোমাদের দুজনকে আল্লাহর পরিপূর্ণ কালিমাসমূহের আশ্রয়ে দিচ্ছি প্রত্যেক শয়তান ও বিষাক্ত প্রাণী থেকে এবং প্রত্যেক ক্ষতিকর দৃষ্টি থেকে।", "নবী ﷺ হাসান ও হুসাইন (রা.)-এর উপর এটি পড়ে ফুঁ দিতেন।", "শিশুদের বদনজর ও অনিষ্ট থেকে রক্ষার মাসনুন দোয়া (এক শিশুর জন্য 'উইযুকা')।"),
        "dua_seeing_afflicted" to DuaText("কাউকে বিপদে দেখলে", "সকল প্রশংসা আল্লাহর, যিনি তোমাকে যা দিয়ে পরীক্ষা করেছেন তা থেকে আমাকে নিরাপদ রেখেছেন এবং তাঁর অনেক সৃষ্টির উপর আমাকে মর্যাদা দিয়েছেন।", "কাউকে বিপদে দেখলে (মনে মনে পড়ুন)।", "পাঠকারী সেই বিপদ থেকে নিরাপদ থাকে।"),
        "dua_istikhara" to DuaText("সালাতুল ইস্তিখারা", "হে আল্লাহ! আমি তোমার জ্ঞানের মাধ্যমে তোমার কাছে কল্যাণ চাই, তোমার কুদরতের মাধ্যমে শক্তি চাই এবং তোমার মহান অনুগ্রহ প্রার্থনা করি। তুমি ক্ষমতাবান, আমি নই; তুমি জানো, আমি জানি না; আর তুমি অদৃশ্য বিষয়ে সম্যক জ্ঞাত। হে আল্লাহ! যদি তোমার জ্ঞানে এই কাজটি (নিজের কাজটি মনে আনুন) আমার দ্বীন, জীবন ও পরিণামের জন্য কল্যাণকর হয়, তবে তা আমার জন্য নির্ধারণ করো, সহজ করো এবং তাতে বরকত দাও। আর যদি তোমার জ্ঞানে এই কাজ আমার দ্বীন, জীবন ও পরিণামের জন্য ক্ষতিকর হয়, তবে তা আমার থেকে এবং আমাকে তা থেকে ফিরিয়ে দাও, আর যেখানেই কল্যাণ থাকুক তা আমার জন্য নির্ধারণ করো, তারপর আমাকে তাতে সন্তুষ্ট করো।", "কোনো বৈধ কাজে কল্যাণ কামনায় দুই রাকাত নফলের পর।", "নবী ﷺ সাহাবিদের সব কাজে ইস্তিখারা এমনভাবে শেখাতেন যেমন কুরআনের সূরা।"),
        "dua_allahumma_bika_asbahna" to DuaText("আল্লাহুম্মা বিকা আসবাহনা", "হে আল্লাহ! তোমার সাহায্যেই আমরা সকালে উপনীত হই ও সন্ধ্যায় উপনীত হই, তোমারই হুকুমে বাঁচি ও মরি, আর তোমারই কাছে পুনরুত্থান।", "সকালে।", "নবী ﷺ সাহাবিদের সকাল-সন্ধ্যা এটি শেখাতেন।"),
        "dua_allahumma_bika_amsayna" to DuaText("আল্লাহুম্মা বিকা আমসাইনা", "হে আল্লাহ! তোমার সাহায্যেই আমরা সন্ধ্যায় উপনীত হই ও সকালে উপনীত হই, তোমারই হুকুমে বাঁচি ও মরি, আর তোমারই কাছে প্রত্যাবর্তন।", "সন্ধ্যায়।", "নবী ﷺ সাহাবিদের সকাল-সন্ধ্যা এটি শেখাতেন।"),
        "dua_afiyah_morning" to DuaText("আফিয়াতের দোয়া", "হে আল্লাহ! আমি তোমার কাছে দুনিয়া ও আখিরাতে ক্ষমা ও নিরাপত্তা চাই।", "নবী ﷺ সকাল-সন্ধ্যা কখনো এই দোয়া ছাড়তেন না।", "নিরাপত্তার চেয়ে উত্তম কিছু কাউকে দেওয়া হয়নি।"),
        "dua_afini_fi_badani" to DuaText("শরীর, শ্রবণ ও দৃষ্টির সুস্থতা", "হে আল্লাহ! আমার শরীরে সুস্থতা দাও, আমার শ্রবণশক্তিতে সুস্থতা দাও, আমার দৃষ্টিতে সুস্থতা দাও। তুমি ছাড়া কোনো ইলাহ নেই।", "সকাল ও সন্ধ্যায় তিনবার করে।", "স্বাস্থ্য ও ইন্দ্রিয়ের হেফাজতের দোয়া।"),
        "dua_ya_hayyu_aslih" to DuaText("আমার সব কাজ ঠিক করে দাও", "হে চিরঞ্জীব, হে ধারক! তোমার রহমতের মাধ্যমে সাহায্য চাই, আমার সব কাজ ঠিক করে দাও এবং এক পলকের জন্যও আমাকে আমার নফসের হাতে ছেড়ে দিও না।", "নবী ﷺ ফাতিমা (রা.)-কে সকাল-সন্ধ্যা পড়ার অসিয়ত করেছেন।", "সব কাজে আল্লাহর সাহায্য প্রার্থনা।"),
        "dua_subhanallah_adada_khalqihi" to DuaText("জুওয়াইরিয়া (রা.)-এর তাসবিহ", "আল্লাহ পবিত্র এবং সকল প্রশংসা তাঁর — তাঁর সৃষ্টির সংখ্যার সমান, তাঁর সন্তুষ্টি অনুযায়ী, তাঁর আরশের ওজনের সমান এবং তাঁর কালিমার কালির সমান।", "সকালে তিনবার — ঘণ্টার পর ঘণ্টা জিকিরের চেয়ে ভারী।", "এই চারটি বাক্য তিনবার বলা সকাল থেকে দুপুর পর্যন্ত জিকিরের চেয়ে ওজনে ভারী।"),
        "dua_salawat" to DuaText("দরুদে ইবরাহিমি", "হে আল্লাহ! মুহাম্মাদ ﷺ ও মুহাম্মাদের পরিবারের উপর রহমত নাজিল করো, যেমন ইবরাহিম (আ.) ও ইবরাহিমের পরিবারের উপর নাজিল করেছ, নিশ্চয়ই তুমি প্রশংসিত, মহিমান্বিত। হে আল্লাহ! মুহাম্মাদ ﷺ ও মুহাম্মাদের পরিবারের উপর বরকত নাজিল করো, যেমন ইবরাহিম (আ.) ও ইবরাহিমের পরিবারের উপর নাজিল করেছ, নিশ্চয়ই তুমি প্রশংসিত, মহিমান্বিত।", "নামাজে ও সর্বদা নবী ﷺ-এর উপর দরুদ।", "যে একবার দরুদ পাঠায়, আল্লাহ তার উপর দশটি রহমত নাজিল করেন (মুসলিম ৪০৮)।"),
        "dua_wudu_after" to DuaText("অজুর পর", "আমি সাক্ষ্য দিচ্ছি যে আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক, তাঁর কোনো শরিক নেই, এবং মুহাম্মাদ ﷺ তাঁর বান্দা ও রাসুল। হে আল্লাহ! আমাকে তওবাকারী ও পবিত্রতা অর্জনকারীদের অন্তর্ভুক্ত করো।", "অজু শেষ করার পর।", "জান্নাতের আটটি দরজা খুলে দেওয়া হয়, যেটি দিয়ে ইচ্ছা প্রবেশ করবে।"),
        "dua_wudu_before" to DuaText("অজুর আগে", "আল্লাহর নামে।", "অজু শুরু করার সময়।", "যে অজুতে আল্লাহর নাম নেয় না তার অজু (পূর্ণ) হয় না।"),
        "dua_istiftah" to DuaText("সানা (নামাজের শুরুর দোয়া)", "হে আল্লাহ! তুমি পবিত্র, তোমার প্রশংসার সাথে, তোমার নাম বরকতময়, তোমার মর্যাদা সুউচ্চ এবং তুমি ছাড়া কোনো ইলাহ নেই।", "নামাজ শুরুতে, তাকবিরে তাহরিমার পরপরই।", "নামাজের মাসনুন শুরুর দোয়া।"),
        "dua_ruku" to DuaText("রুকুতে", "আমার মহান রব পবিত্র।", "রুকুতে অন্তত তিনবার।", "রুকুর মাসনুন তাসবিহ।"),
        "dua_sujood" to DuaText("সিজদায়", "আমার সর্বোচ্চ রব পবিত্র।", "সিজদায় অন্তত তিনবার।", "বান্দা সিজদায় তার রবের সবচেয়ে নিকটে থাকে (মুসলিম ৪৮২)।"),
        "dua_rising_ruku" to DuaText("রুকু থেকে ওঠার সময়", "যে আল্লাহর প্রশংসা করে আল্লাহ তা শোনেন। হে আমাদের রব! সকল প্রশংসা তোমারই।", "রুকু থেকে উঠতে এবং সোজা দাঁড়িয়ে।", "যার 'রাব্বানা ওয়া লাকাল হামদ' ফেরেশতাদের সাথে মিলে যায় তার পূর্বের গুনাহ মাফ।"),
        "dua_between_sajdas" to DuaText("দুই সিজদার মাঝে", "হে আমার রব! আমাকে ক্ষমা করো, হে আমার রব! আমাকে ক্ষমা করো।", "দুই সিজদার মাঝে বসে।", "জলসার মাসনুন দোয়া।"),
        "dua_before_salam_four" to DuaText("চারটি বিষয় থেকে আশ্রয় (সালামের আগে)", "হে আল্লাহ! আমি তোমার আশ্রয় চাই জাহান্নামের আজাব থেকে, কবরের আজাব থেকে, জীবন ও মৃত্যুর ফিতনা থেকে এবং মাসিহ দাজ্জালের ফিতনার অনিষ্ট থেকে।", "শেষ তাশাহহুদ ও দরুদের পর, সালামের আগে।", "নবী ﷺ এই চারটি বিষয় থেকে আশ্রয় চাওয়ার আদেশ দিয়েছেন।"),
        "dua_qunoot_witr" to DuaText("বিতরে কুনুত", "হে আল্লাহ! যাদের তুমি হেদায়েত দিয়েছ তাদের মধ্যে আমাকে হেদায়েত দাও, যাদের নিরাপত্তা দিয়েছ তাদের মধ্যে আমাকে নিরাপত্তা দাও, যাদের অভিভাবকত্ব নিয়েছ তাদের মধ্যে আমার অভিভাবকত্ব নাও, যা দিয়েছ তাতে বরকত দাও এবং যা ফয়সালা করেছ তার অনিষ্ট থেকে রক্ষা করো। নিশ্চয়ই তুমি ফয়সালা করো, তোমার বিরুদ্ধে ফয়সালা হয় না, আর তুমি যার বন্ধু সে অপমানিত হয় না। হে আমাদের রব! তুমি বরকতময় ও সুউচ্চ।", "বিতরের নামাজে — নবী ﷺ হাসান ইবনে আলী (রা.)-কে শিখিয়েছেন।", "বিতরের মাসনুন কুনুত। (হানাফিদের কাছে 'আল্লাহুম্মা ইন্না নাসতাঈনুকা'-ও প্রসিদ্ধ।)"),
        "dua_qunoot_hanafi" to DuaText("কুনুত (আল্লাহুম্মা ইন্না নাসতাঈনুকা)", "হে আল্লাহ! আমরা তোমার কাছে সাহায্য ও ক্ষমা চাই, তোমার প্রতি ঈমান আনি ও ভরসা করি, তোমার উত্তম প্রশংসা করি, তোমার শুকরিয়া আদায় করি, অকৃতজ্ঞ হই না, আর যে তোমার অবাধ্য হয় তাকে পরিত্যাগ করি। হে আল্লাহ! আমরা তোমারই ইবাদত করি, তোমারই জন্য নামাজ পড়ি ও সিজদা করি, তোমারই দিকে ছুটে যাই, তোমার রহমতের আশা করি ও তোমার আজাবকে ভয় করি; নিশ্চয়ই তোমার আজাব কাফিরদের উপর আপতিত হবে।", "বিতরে — হানাফিদের আমল।", "উমর (রা.) থেকে কুনুতে বর্ণিত।"),
        "dua_sleep_aslamtu" to DuaText("ঘুমানোর আগে শেষ কথা", "হে আল্লাহ! আমি নিজেকে তোমার কাছে সমর্পণ করলাম, আমার বিষয় তোমার উপর ন্যস্ত করলাম, আমার পিঠ তোমার আশ্রয়ে দিলাম, তোমার প্রতি আশা ও ভয় নিয়ে। তোমার থেকে বাঁচার কোনো আশ্রয় ও মুক্তি নেই তোমার কাছে ছাড়া। আমি ঈমান এনেছি তোমার নাজিল করা কিতাবের উপর এবং তোমার পাঠানো নবীর উপর।", "অজু করে ডান কাতে শুয়ে — সর্বশেষ কথা।", "সেই রাতে মারা গেলে ফিতরাতের (ইসলামের) উপর মৃত্যু হবে।"),
        "dua_waking_night" to DuaText("রাতে ঘুম ভাঙলে", "আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি একক, তাঁর কোনো শরিক নেই, রাজত্ব ও প্রশংসা তাঁরই এবং তিনি সব কিছুর উপর ক্ষমতাবান। সকল প্রশংসা আল্লাহর, আল্লাহ পবিত্র, আল্লাহ ছাড়া কোনো ইলাহ নেই, আল্লাহ সবচেয়ে বড়, আর আল্লাহ ছাড়া কোনো শক্তি ও ক্ষমতা নেই। হে আল্লাহ! আমাকে ক্ষমা করো।", "রাতে ঘুম ভাঙলে।", "দোয়া কবুল হয়, আর অজু করে নামাজ পড়লে নামাজ কবুল হয়।"),
        "dua_hamm_ibn_masud" to DuaText("দুঃখের দোয়া (ইবনে মাসউদ)", "হে আল্লাহ! আমি তোমার বান্দা, তোমার বান্দার পুত্র, তোমার বান্দীর পুত্র। আমার কপাল তোমার হাতে, আমার উপর তোমার হুকুম কার্যকর, আমার ব্যাপারে তোমার ফয়সালা ন্যায়সঙ্গত। আমি তোমার কাছে প্রার্থনা করি তোমার প্রত্যেক সেই নামের উসিলায় যা তুমি নিজের জন্য রেখেছ, বা তোমার কিতাবে নাজিল করেছ, বা তোমার কোনো সৃষ্টিকে শিখিয়েছ, বা তোমার কাছে অদৃশ্য জ্ঞানে সংরক্ষিত রেখেছ — যেন কুরআনকে আমার অন্তরের বসন্ত, আমার বক্ষের আলো, আমার দুঃখের প্রতিকার এবং আমার দুশ্চিন্তা দূরকারী বানিয়ে দাও।", "দুঃখ ও দুশ্চিন্তায় — আল্লাহ দুঃখকে আনন্দে বদলে দেন।", "আল্লাহ তার দুশ্চিন্তা ও দুঃখ দূর করে আনন্দ দান করেন।"),
        "dua_difficulty_sahl" to DuaText("যখন কোনো কাজ কঠিন হয়", "হে আল্লাহ! কোনো কিছুই সহজ নয় যা তুমি সহজ না করো, আর তুমি চাইলে কঠিনকে সহজ করে দাও।", "কোনো কাজ কঠিন মনে হলে।", "পরীক্ষা ও কঠিন কাজে সহজতা।"),
        "dua_musibah" to DuaText("বিপদে (ইস্তিরজা)", "আমরা আল্লাহরই এবং তাঁরই দিকে ফিরে যাব। হে আল্লাহ! আমার বিপদে আমাকে প্রতিদান দাও এবং এর চেয়ে উত্তম বিকল্প দাও।", "যেকোনো ক্ষতি বা বিপদে।", "আল্লাহ অবশ্যই উত্তম বিকল্প দেন — উম্মে সালামা (রা.) নবী ﷺ-কে পেয়েছিলেন।"),
        "dua_debt" to DuaText("ঋণমুক্তির জন্য", "হে আল্লাহ! তোমার হালাল দিয়ে আমাকে হারাম থেকে বাঁচিয়ে যথেষ্ট করো এবং তোমার অনুগ্রহে আমাকে তুমি ছাড়া সবার থেকে অমুখাপেক্ষী করো।", "ঋণ পরিশোধের জন্য — আলী (রা.) শিখিয়েছেন।", "পাহাড় সমান ঋণ হলেও আল্লাহ পরিশোধ করিয়ে দেন।"),
        "dua_anger" to DuaText("রাগের সময়", "আমি বিতাড়িত শয়তান থেকে আল্লাহর আশ্রয় চাই।", "রাগ হলে।", "নবী ﷺ বলেছেন: যদি সে এটি বলে তবে তার রাগ চলে যাবে।"),
        "dua_waswasa" to DuaText("ঈমানে ওয়াসওয়াসার বিরুদ্ধে", "আমি আল্লাহ ও তাঁর রাসুলদের উপর ঈমান এনেছি।", "ঈমান সম্পর্কে শয়তানি ওয়াসওয়াসা এলে।", "ওয়াসওয়াসা এলে এটি বলে থেমে যাও (আউযুবিল্লাহও পড়ো)।"),
        "dua_travel_full" to DuaText("সফরের পূর্ণ দোয়া", "হে আল্লাহ! আমরা এই সফরে তোমার কাছে নেকি ও তাকওয়া চাই এবং এমন আমল যা তুমি পছন্দ করো। হে আল্লাহ! আমাদের এই সফর সহজ করে দাও এবং এর দূরত্ব কমিয়ে দাও। হে আল্লাহ! তুমিই সফরের সঙ্গী এবং পরিবারের তত্ত্বাবধায়ক।", "সফরে রওনা হওয়ার সময়, 'সুবহানাল্লাযি সাখখারা'-র পর।", "সফরের পূর্ণ মাসনুন দোয়া।"),
        "dua_return_travel" to DuaText("সফর থেকে ফেরা", "আমরা প্রত্যাবর্তনকারী, তওবাকারী, ইবাদতকারী এবং আমাদের রবের প্রশংসাকারী।", "সফর থেকে ফেরার সময়।", "নবী ﷺ সফর থেকে ফিরে এটি বলতেন।"),
        "dua_farewell_traveller" to DuaText("মুসাফিরকে বিদায়", "আমি তোমার দ্বীন, তোমার আমানত এবং তোমার আমলের পরিণাম আল্লাহর কাছে সোপর্দ করলাম।", "মুসাফিরকে বিদায় দেওয়ার সময়।", "আল্লাহর কাছে সোপর্দ করা জিনিস নষ্ট হয় না।"),
        "dua_entering_town" to DuaText("কোথাও অবস্থান করা", "আমি আল্লাহর পরিপূর্ণ কালিমাসমূহের আশ্রয় চাই তাঁর সকল সৃষ্টির অনিষ্ট থেকে।", "কোথাও যাত্রাবিরতি বা নতুন শহরে পৌঁছে।", "সেখান থেকে রওনা হওয়া পর্যন্ত কিছুই ক্ষতি করবে না।"),
        "dua_boarding_ship" to DuaText("নৌকা/বাহনে আরোহণ", "আল্লাহরই নামে এর চলা ও থামা, নিশ্চয়ই আমার রব ক্ষমাশীল, দয়ালু।", "নৌকা বা বাহনে আরোহণের সময় — নূহ (আ.)-এর উক্তি।", "কুরআনের আয়াত — নূহ (আ.)-এর নৌকার দোয়া।"),
        "dua_istighfar_hayyul_qayyum" to DuaText("হাইয়ুল কাইয়ুমসহ ইস্তিগফার", "আমি সেই আল্লাহর কাছে ক্ষমা চাই যিনি ছাড়া কোনো ইলাহ নেই, যিনি চিরঞ্জীব ও ধারক, এবং তাঁর দিকে তওবা করি।", "তওবার জন্য।", "গুনাহ মাফ হয়ে যায়, যদিও সে যুদ্ধক্ষেত্র থেকে পালিয়ে থাকে।"),
        "dua_rabbighfir_warham" to DuaText("রাব্বিগফির ওয়ারহাম", "হে আমার রব! ক্ষমা করো ও দয়া করো, আর তুমিই শ্রেষ্ঠ দয়ালু।", "কুরআনি দোয়া — ক্ষমা ও রহমত।", "সূরা মুমিনুনের শেষ আয়াত।"),
        "dua_majlis_kaffarah" to DuaText("মজলিসের কাফফারা", "হে আল্লাহ! তুমি পবিত্র, তোমার প্রশংসার সাথে। আমি সাক্ষ্য দিচ্ছি যে তুমি ছাড়া কোনো ইলাহ নেই। আমি তোমার কাছে ক্ষমা চাই এবং তোমার দিকে তওবা করি।", "মজলিস/বৈঠক থেকে ওঠার সময়।", "মজলিসে যা ভুল কথা হয়েছে তার কাফফারা হয়ে যায়।"),
        "dua_jami_forgiveness" to DuaText("ব্যাপক ক্ষমা", "হে আল্লাহ! আমার ভুল, আমার অজ্ঞতা, আমার কাজে আমার বাড়াবাড়ি এবং যা তুমি আমার চেয়ে বেশি জানো সব ক্ষমা করে দাও।", "নবী ﷺ-এর ব্যাপক দোয়া।", "নবী ﷺ এই দোয়া করতেন।"),
        "dua_parents_nuh" to DuaText("পিতা-মাতার জন্য নূহ (আ.)-এর দোয়া", "হে আমার রব! আমাকে, আমার পিতা-মাতাকে, যে ঈমান নিয়ে আমার ঘরে প্রবেশ করে তাকে এবং সকল মুমিন নারী-পুরুষকে ক্ষমা করো।", "পিতা-মাতা ও মুমিনদের জন্য।", "নূহ (আ.)-এর দোয়া।"),
        "dua_shukr_parents" to DuaText("পিতা-মাতার নিয়ামতের শুকরিয়া ও নেক সন্তান", "হে আমার রব! আমাকে তাওফিক দাও যেন আমি তোমার সেই নিয়ামতের শুকরিয়া আদায় করি যা তুমি আমাকে ও আমার পিতা-মাতাকে দিয়েছ, এবং এমন নেক আমল করি যা তুমি পছন্দ করো, আর আমার সন্তানদেরও নেককার বানাও। আমি তোমার দিকে তওবা করছি এবং আমি আত্মসমর্পণকারীদের অন্তর্ভুক্ত।", "চল্লিশ বছর বয়সের কুরআনি দোয়া।", "শুকরিয়া, নেক আমল ও সন্তানের সংশোধন — সব এক দোয়ায়।"),
        "dua_intimacy" to DuaText("দাম্পত্য মিলনের আগে", "আল্লাহর নামে। হে আল্লাহ! আমাদের শয়তান থেকে দূরে রাখো এবং তুমি আমাদের যে (সন্তান) দেবে তাকেও শয়তান থেকে দূরে রাখো।", "স্বামী-স্ত্রীর মিলনের আগে।", "সন্তান নির্ধারিত হলে শয়তান কখনো তার ক্ষতি করবে না।"),
        "dua_ibrahim_children_protection" to DuaText("ঘর ও সন্তানের হেফাজত", "হে আমার রব! এই শহরকে নিরাপদ করো এবং আমাকে ও আমার সন্তানদের মূর্তিপূজা থেকে দূরে রাখো।", "ইবরাহিম (আ.)-এর দোয়া — শহর ও সন্তানের হেফাজত।", "তাওহিদের উপর অবিচল থাকার দোয়া।"),
        "dua_drinking_milk" to DuaText("দুধ পান করার সময়", "হে আল্লাহ! আমাদের জন্য এতে বরকত দাও এবং আমাদের আরও বেশি দাও।", "দুধ পান করলে।", "দুধ খাদ্য ও পানীয় উভয়ের জন্য যথেষ্ট।"),
        "dua_iftar_host" to DuaText("কারও বাড়িতে ইফতার করলে", "তোমাদের কাছে রোজাদাররা ইফতার করুক, নেককাররা তোমাদের খাবার খাক এবং ফেরেশতারা তোমাদের জন্য দোয়া করুক।", "কারও বাড়িতে ইফতার করলে।", "মেজবানের জন্য নবী ﷺ-এর দোয়া।"),
        "dua_seeing_first_fruit" to DuaText("মৌসুমের প্রথম ফল দেখলে", "হে আল্লাহ! আমাদের ফলে, আমাদের শহরে, আমাদের সা' ও মুদ্দে (মাপজোখে) বরকত দাও।", "মৌসুমের প্রথম ফল দেখে।", "রিজিক ও শহরে বরকতের দোয়া।"),
        "dua_good_news" to DuaText("সুসংবাদ পেলে", "সকল প্রশংসা সেই আল্লাহর, যাঁর নিয়ামতে ভালো কাজগুলো পূর্ণ হয়।", "খুশির খবর পেলে (এবং সিজদায়ে শুকর)।", "নবী ﷺ পছন্দনীয় কিছু দেখলে এটি বলতেন।"),
        "dua_looking_mirror" to DuaText("আয়না দেখার সময়", "হে আল্লাহ! যেমন তুমি আমার চেহারা সুন্দর করেছ, তেমনি আমার চরিত্রও সুন্দর করে দাও।", "আয়না দেখার সময়।", "নবী ﷺ এই দোয়া করতেন (আয়নার শর্ত ছাড়াও প্রমাণিত)।"),
        "dua_rabbana_taqabbal" to DuaText("আমল কবুলের দোয়া", "হে আমাদের রব! আমাদের থেকে কবুল করো, নিশ্চয়ই তুমি সর্বশ্রোতা, সর্বজ্ঞ। আর আমাদের তওবা কবুল করো, নিশ্চয়ই তুমি তওবা কবুলকারী, দয়ালু।", "ইবরাহিম ও ইসমাইল (আ.) কাবা নির্মাণের সময় চেয়েছিলেন।", "প্রত্যেক নেক আমলের পর কবুলের দোয়া।"),
    )
}
